async function loadAuditLogs(){const root=document.getElementById("auditLogRoot"),summary=document.getElementById("auditSummary");root.innerHTML="กำลังโหลด Audit Log...";try{const params={from:val("auditFrom"),to:val("auditTo"),actor:val("auditActor"),action:val("auditAction"),source:val("auditSource"),success:val("auditSuccess"),bookingCode:val("auditBookingCode"),limit:"1000"};const rows=await API.audit(params);summary.innerText=`พบ ${rows.length.toLocaleString("th-TH")} เหตุการณ์ (แสดงสูงสุด 1,000 รายการ)`;root.innerHTML=rows.length?`<table class="data-table audit-table"><thead><tr><th>วันเวลา</th><th>หมวด / เหตุการณ์</th><th>ผล</th><th>ผู้ดำเนินการ</th><th>รายการ</th><th>รายละเอียด</th><th>ข้อมูลเปลี่ยนแปลง</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${escapeHtml(new Date(row.occurredAt).toLocaleString("th-TH"))}</td><td><b>${escapeHtml(row.source)}</b><br>${escapeHtml(row.action)}</td><td><span class="${row.success?"audit-ok":"audit-fail"}">${row.success?"สำเร็จ":"ล้มเหลว"}</span>${row.statusCode?`<br>HTTP ${Number(row.statusCode)}`:""}</td><td>${escapeHtml(row.actor||"ระบบ")}<br><small>${escapeHtml(row.role||"")}${row.ipAddress?` · ${escapeHtml(row.ipAddress)}`:""}</small></td><td>${escapeHtml(row.entityType||"")} ${escapeHtml(row.entityId||"")}<br><b>${escapeHtml(row.bookingCode||"")}</b></td><td>${escapeHtml(row.detail||"")}${row.amount!==undefined&&row.amount!==null?`<br>฿${money(row.amount)}`:""}${row.requestPath?`<br><small>${escapeHtml(row.requestPath)}</small>`:""}</td><td>${auditJson({before:row.before,after:row.after})}</td></tr>`).join("")}</tbody></table>`:"ไม่พบเหตุการณ์ตามตัวกรอง"}catch(error){root.innerHTML=`<div class="error">${escapeHtml(error.message)}</div>`}}
