const documentProfiles={REGISTER:{title:"ใบยืนยันการจอง (Register)",contact:true,source:true,agent:true,transport:true,status:true,price:true,program:true,van:false,equipment:false,notes:false,allergy:false},MONEY_RECEIPT:{title:"ใบสำคัญรับเงิน",status:true,price:true,program:true,equipment:true,notes:true,allergy:true,paid:true},EQUIPMENT_SLIP:{title:"ใบอุปกรณ์",price:true,equipment:true},VAN_RECEIPT:{title:"ใบเสร็จรถตู้",transport:true,price:true,van:true},BOAT_TICKET:{title:"ตั๋วเรือ",program:true},ISLAND_PURCHASE_ORDER:{title:"ใบสั่งซื้อจากเกาะ",price:true,islandOnly:true}};
function documentPaxSummary(booking){const groups=new Map();for(const person of booking.passengers||[]){const type=passengerTypeLabels[person.passengerType||"adult"]||"ผู้ใหญ่",nationality=person.nationalityType==="foreign"?"ต่างชาติ":"ไทย",key=`${type} (${nationality})`,row=groups.get(key)||{label:key,qty:0};row.qty++;groups.set(key,row)}return[...groups.values()]}
function addonVisibleOnDocument(item,profile){const field={"ใบยืนยันการจอง (Register)":"show_register","ใบสำคัญรับเงิน":"show_money_receipt","ใบอุปกรณ์":"show_equipment_slip","ใบเสร็จรถตู้":"show_van_receipt","ตั๋วเรือ":"show_boat_ticket","ใบสั่งซื้อจากเกาะ":"show_island_purchase_order"}[profile.title];if(item.documentVisibility&&field in item.documentVisibility)return item.documentVisibility[field]===true;const configured=(master.addOns||[]).find(addon=>addon.addon_id===item.id);if(configured&&field in configured)return configured[field]===true;return field==="show_money_receipt"||field==="show_equipment_slip"}
function transportationVisibleOnDocument(person,booking,profile){const field={"ใบยืนยันการจอง (Register)":"show_register","ใบสำคัญรับเงิน":"show_money_receipt","ใบอุปกรณ์":"show_equipment_slip","ใบเสร็จรถตู้":"show_van_receipt","ตั๋วเรือ":"show_boat_ticket"}[profile.title],name=person.transportationMethod||booking.transportationMethod||"",configured=(master.transportationMethods||[]).find(method=>method.method_name===name);if(configured&&field in configured)return configured[field]===true;return field==="show_register"||field==="show_van_receipt"}
function accommodationVisibleOnDocument(person,profile){const field={"ใบยืนยันการจอง (Register)":"show_register","ใบสำคัญรับเงิน":"show_money_receipt","ใบอุปกรณ์":"show_equipment_slip","ใบเสร็จรถตู้":"show_van_receipt","ตั๋วเรือ":"show_boat_ticket"}[profile.title],configured=(master.accommodations||[]).find(item=>item.accommodation_id===person.accommodationId);if(configured&&field in configured)return configured[field]===true;return field==="show_register"||field==="show_money_receipt"}
function documentGroupedItems(booking,profile){const groups=new Map(),add=(name,qty,unit)=>{const key=`${name}:${unit}`,row=groups.get(key)||{name,qty:0,unit,total:0};row.qty+=qty;row.total+=qty*unit;groups.set(key,row)};for(const person of booking.passengers||[]){if(profile.program&&person.program){const type=passengerTypeLabels[person.passengerType||"adult"]||"ผู้ใหญ่",nationality=person.nationalityType==="foreign"?"ต่างชาติ":"ไทย";add(`${person.program.name||"โปรแกรมทัวร์"} - ${type} (${nationality})`,Number(person.program.qty||1),Number(person.program.price||0))}if(profile.van&&(person.transportationMethod||Number(person.transportationAmount||0))&&transportationVisibleOnDocument(person,booking,profile))add(`ค่ารถตู้/เดินทาง - ${person.transportationMethod||booking.transportationMethod||"ไม่ระบุ"}`,1,Number(person.transportationAmount||0));for(const item of [...(person.preAddOns||[]).filter(row=>row.selected),...(person.islandAddOns||[])])if(addonVisibleOnDocument(item,profile))add(`ค่าอุปกรณ์- ${item.name||"อื่นๆ"}`,Number(item.qty||1),Number(item.price||0))}return[...groups.values()]}
function documentInfoLine(label,value){return`<div><b>${escapeHtml(label)}:</b> ${escapeHtml(value||"-")}</div>`}
renderReceipt=function(booking,type="MONEY_RECEIPT"){const profile=documentProfiles[type]||documentProfiles.MONEY_RECEIPT,company=getCompanySettings(),leader=[booking.leaderTitle,booking.leaderFirstName,booking.leaderLastName].filter(Boolean).join(" "),pax=documentPaxSummary(booking),items=documentGroupedItems(booking,profile),subtotal=items.reduce((sum,item)=>sum+item.total,0),allergies=[...new Set((booking.passengers||[]).map(person=>person.foodAllergy).filter(Boolean))].join(", "),logo=company.logo_url||company.logoUrl?`<img class="document-logo" src="${escapeHtml(company.logo_url||company.logoUrl)}" onerror="this.style.display='none'">`:`<div class="document-logo-placeholder"></div>`,reference=type==="BOAT_TICKET"?`เล่มที่ ${escapeHtml(booking.boatTicketBookNo||"-")} เลขที่ ${escapeHtml(booking.boatTicketNo||"-")}`:`เล่มที่ ${escapeHtml(booking.receiptBookNo||"-")} เลขที่ ${escapeHtml(booking.manualReceiptNo||"-")}`;return`<div class="document-actions"><button class="btn primary" onclick="window.print()">Print / Save PDF</button><button class="btn soft" onclick="window.close()">Close</button></div><div class="document-page document-${type.toLowerCase()}"><div class="document-header"><div class="document-company">${logo}<div><h2>${escapeHtml(company.company_name||"Sabina Tour Booking")}</h2><div>${escapeHtml(company.address||"")}</div><div>โทร ${escapeHtml(company.phone||"-")}</div><div>เลขประจำตัวผู้เสียภาษี ${escapeHtml(company.tax_id||"-")}</div></div></div><div class="document-title"><h1>${profile.title}</h1><div>${reference}</div><div>Booking: ${escapeHtml(booking.bookingCode||"DRAFT")}</div><div>วันที่ออก: ${new Date().toLocaleDateString("th-TH")}</div></div></div><div class="document-meta"><div class="document-box"><strong>ข้อมูลผู้จอง</strong>${documentInfoLine("ชื่อหัวหน้าทริป",leader)}${profile.contact?documentInfoLine("เบอร์",booking.phone):""}${profile.contact?documentInfoLine("Contact",booking.contactEmail):""}${profile.source?documentInfoLine("Source",booking.source):""}${profile.agent?documentInfoLine("Agent",booking.agentName):""}</div><div class="document-box"><strong>ข้อมูลการเดินทาง</strong>${documentInfoLine("วันไป",booking.travelDate)}${documentInfoLine("วันกลับ",booking.returnDate)}${profile.transport?documentInfoLine("Transportation",booking.transportationMethod||[...new Set((booking.passengers||[]).map(person=>person.transportationMethod).filter(Boolean))].join(", ")):""}${profile.status?documentInfoLine("Status",booking.status):""}</div></div><h3>สรุปจำนวนผู้เดินทาง</h3><table class="document-table document-pax-table"><thead><tr><th>ประเภท</th><th class="num">จำนวน</th></tr></thead><tbody>${pax.map(row=>`<tr><td>${escapeHtml(row.label)}</td><td class="num">${row.qty}</td></tr>`).join("")||`<tr><td colspan="2">ไม่ระบุ</td></tr>`}</tbody></table>${items.length?`<h3>รายการ</h3><table class="document-table"><thead><tr><th>รายการ</th><th class="num">จำนวน</th>${profile.price?`<th class="num">ราคาต่อหน่วย</th><th class="num">รวม</th>`:""}</tr></thead><tbody>${items.map(item=>`<tr><td>${escapeHtml(item.name)}</td><td class="num">${item.qty}</td>${profile.price?`<td class="num">${money(item.unit)}</td><td class="num">${money(item.total)}</td>`:""}</tr>`).join("")}</tbody></table>`:`<div class="document-empty">ไม่มีรายการสำหรับเอกสารประเภทนี้</div>`}${profile.price?`<div class="document-total"><div class="document-total-row grand"><span>รวมรายการในเอกสาร</span><b>${money(subtotal)} บาท</b></div>${["MONEY_RECEIPT","REGISTER"].includes(type)?`<div class="document-total-row"><span>ยอด Booking</span><b>${money(booking.totalAmount)} บาท</b></div><div class="document-total-row"><span>มัดจำ (${escapeHtml(booking.depositPaymentMethod||"-")})</span><b>${money(booking.depositAmount)} บาท</b></div><div class="document-total-row"><span>ขายเชื่อ (${escapeHtml(booking.creditPaymentMethod||"-")})</span><b>${money(booking.creditAmount)} บาท</b></div>`:""}</div>`:""}${profile.notes&&booking.bookingNote?`<div class="document-note"><b>หมายเหตุ:</b> ${escapeHtml(booking.bookingNote)}</div>`:""}${profile.allergy?`<div class="document-note"><b>ข้อมูลแพ้อาหาร:</b> ${escapeHtml(allergies||"ไม่มีข้อมูล")}</div>`:""}${profile.paid?`<div class="paid-stamp">RECEIVED</div>`:""}<div class="document-audit-line">จัดทำโดย ${escapeHtml(currentUser?.displayName||currentUser?.username||"ระบบ")} · พิมพ์ ${new Date().toLocaleString("th-TH")} · อ้างอิง ${escapeHtml(booking.bookingCode||"DRAFT")}</div><div class="document-footer"><div><div class="signature-line">ผู้จัดทำ / ผู้รับเงิน</div></div><div><div class="signature-line">ผู้รับเอกสาร / ลูกค้า</div></div></div></div>`};
function documentPaxMatrix(booking){const columns=[["adult","thai","ผู้ใหญ่ (ไทย)"],["adult","foreign","ผู้ใหญ่ (ต่างชาติ)"],["child","thai","เด็ก (ไทย)"],["child","foreign","เด็ก (ต่างชาติ)"],["infant","thai","ทารก (ไทย)"],["infant","foreign","ทารก (ต่างชาติ)"],["foc","thai","FOC (ไทย)"],["foc","foreign","FOC (ต่างชาติ)"]],people=booking.passengers||[],counts=columns.map(([type,nationality])=>people.filter(person=>(person.passengerType||"adult")===type&&(person.nationalityType||"thai")===nationality).length);return`<h3>สรุปจำนวนผู้เดินทาง</h3><table class="document-table document-pax-table document-pax-matrix"><thead><tr>${columns.map(([, ,label])=>`<th>${label}</th>`).join("")}<th>รวม</th></tr></thead><tbody><tr>${counts.map(qty=>`<td>${qty}</td>`).join("")}<td>${people.length}</td></tr></tbody></table>`}
const renderReceiptWithVerticalPax=renderReceipt;renderReceipt=function(booking,type="MONEY_RECEIPT"){let html=renderReceiptWithVerticalPax(booking,type).replace(/<h3>สรุปจำนวนผู้เดินทาง<\/h3><table class="document-table document-pax-table">[\s\S]*?<\/table>/,documentPaxMatrix(booking));const reference=type==="MONEY_RECEIPT"?`<div>เล่มที่ (ตั๋วเรือ) ${escapeHtml(booking.boatTicketBookNo||"-")} เลขที่ (ตั๋วเรือ) ${escapeHtml(booking.boatTicketNo||"-")}</div>`:"";return html.replace(/<div>เล่มที่ [\s\S]*?<\/div><div>Booking:/,`${reference}<div>Booking:`)};
const documentGroupedItemsBase=documentGroupedItems;documentGroupedItems=function(booking,profile){let rows;if(profile.title==="ใบเสร็จรถตู้"){const groups=new Map();for(const person of booking.passengers||[]){const unit=Number(person.transportationAmount||0);if((!person.transportationMethod&&!unit)||!transportationVisibleOnDocument(person,booking,profile))continue;const method=person.transportationMethod||booking.transportationMethod||"ไม่ระบุ",type=passengerTypeLabels[person.passengerType||"adult"]||"ผู้ใหญ่",nationality=person.nationalityType==="foreign"?"ต่างชาติ":"ไทย",name=`รถตู้ - ${type} (${nationality}) - ${method}`,key=`${name}:${unit}`,row=groups.get(key)||{name,qty:0,unit,total:0};row.qty+=1;row.total+=unit;groups.set(key,row)}rows=[...groups.values()];for(const person of booking.passengers||[])for(const item of [...(person.preAddOns||[]).filter(row=>row.selected),...(person.islandAddOns||[])])if(addonVisibleOnDocument(item,profile)){const qty=Number(item.qty||1),unit=Number(item.price||0),name=`ค่าอุปกรณ์- ${item.name||"อื่นๆ"}`,key=`${name}:${unit}`,row=groups.get(key)||{name,qty:0,unit,total:0};row.qty+=qty;row.total+=qty*unit;groups.set(key,row)}rows=[...groups.values()]}else rows=documentGroupedItemsBase(booking,profile);if(profile.title.includes("Register")||profile.title==="ใบสำคัญรับเงิน"){const credit=(booking.passengers||[]).reduce((sum,person)=>sum+Number(person.tentCreditAmount||0),0);if(credit>0)rows.push({name:"เครดิตคืนค่าเต็นท์",qty:1,unit:-credit,total:-credit})}const rank=name=>/เครดิต|คืนเงิน/.test(name)?4:/รถตู้|เดินทาง/.test(name)?2:/อุปกรณ์|เต็นท์|เหมาลำ|เหมาเรือ|ดำน้ำ/.test(name)?3:1;return rows.map((row,index)=>({...row,_index:index})).sort((a,b)=>rank(a.name)-rank(b.name)||a._index-b._index)};
const documentGroupedItemsWithServices=documentGroupedItems;documentGroupedItems=function(booking,profile){const rows=documentGroupedItemsWithServices(booking,profile),groups=new Map();for(const person of booking.passengers||[]){if(!person.accommodationId||!accommodationVisibleOnDocument(person,profile))continue;const arrangement=person.accommodationBookedBy==="company"?"จองให้":"ลูกค้าจองเอง",name=`ที่พัก - ${person.accommodationName||person.accommodationId} (${arrangement}, ไม่รวมรายได้)`,row=groups.get(name)||{name,qty:0,unit:0,total:0};row.qty+=1;groups.set(name,row)}rows.push(...groups.values());const rank=name=>/เครดิต|คืนเงิน/.test(name)?5:/รถตู้|เดินทาง/.test(name)?2:/ที่พัก/.test(name)?3:/อุปกรณ์|เต็นท์|เหมาลำ|เหมาเรือ|ดำน้ำ/.test(name)?4:1;return rows.map((row,index)=>({...row,_index:index})).sort((a,b)=>rank(a.name)-rank(b.name)||a._index-b._index)};
