exportBookingExcel=async function(){const from=val("pcDate"),to=val("pcToDate")||from;if(!from)return alert("เลือกวันที่เริ่มต้น");if(to<from)return alert("วันที่สิ้นสุดต้องไม่น้อยกว่าวันเริ่มต้น");try{const rows=(await API.bookings()).filter(booking=>booking.status!=="cancelled"&&booking.travelDate>=from&&booking.travelDate<=to),headers=["User","Agent","จองในงาน","วันที่จอง","เล่มที่","เลขที่","เลขตั๋วเรือ","ชื่อลูกค้า","เบอร์โทร","จำนวน","เด็ก","FOC","โปรแกรม","ราคาขาย","มัดจำ","วันมา","วันกลับ","เดินทางโดย","เดินทางกลับ","ที่พัก","ช่องทางติดต่อ","หมายเหตุ"],csv="\uFEFF"+[headers,...rows.map(bookingExcelRow)].map(row=>row.map(excelCell).join(",")).join("\r\n"),blob=new Blob([csv],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=`Sabina-Booking-${from}-${to}.csv`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}catch(error){alert(error.message||"ดาวน์โหลด Excel ไม่สำเร็จ")}};
