async function previewPassengerCsv(file){if(!file)return;const text=await file.text(),result=parsePassengerCsv(text);csvImportResult=result;const counts={adult:0,child:0,infant:0,foc:0};result.rows.forEach(row=>counts[row.passengerType]++);const warnings=[...(result.errors||[]),...(result.duplicates||[])];document.getElementById("csvImportSummary").innerHTML=`<div class="csv-summary"><b>${result.rows.length} คน</b> · ผู้ใหญ่ ${counts.adult} · เด็ก ${counts.child} · ทารก ${counts.infant} · FOC ${counts.foc}</div>${warnings.length?`<div class="error">${warnings.map(escapeHtml).join("<br>")}</div>`:"<div class='audit-ok'>ตรวจรูปแบบผ่าน พร้อมนำเข้า</div>"}`;document.getElementById("csvImportPreview").innerHTML=result.rows.length?`<table class="data-table"><thead><tr><th>แถว</th><th>ชื่อ-สกุล</th><th>ประเภท</th><th>สัญชาติ</th><th>โทร</th><th>โปรแกรม</th><th>จุดรับ/เดินทาง</th></tr></thead><tbody>${result.rows.map(row=>`<tr><td>${row.sourceRow}</td><td>${escapeHtml([row.title,row.firstName,row.lastName].filter(Boolean).join(" "))}</td><td>${escapeHtml(passengerTypeLabels[row.passengerType])}</td><td>${row.nationalityType==="foreign"?"ต่างชาติ":"ไทย"}</td><td>${escapeHtml(row.phone)}</td><td>${escapeHtml(row.programName)}</td><td>${escapeHtml([row.pickupLocation,row.transportationMethod].filter(Boolean).join(" / "))}</td></tr>`).join("")}</tbody></table>`:"";document.getElementById("confirmCsvImportBtn").disabled=!result.ok||!result.rows.length||result.duplicates.length>0}
function importedPassenger(row,index){const person=createPassenger(index,row.passengerType),program=(master.programs||[]).find(item=>String(item.program_name).trim().toLowerCase()===String(row.programName).trim().toLowerCase()),accommodation=(master.accommodations||[]).find(item=>String(item.accommodation_name).trim().toLowerCase()===String(row.accommodationName).trim().toLowerCase());Object.assign(person,row,{isLeader:index===0});if(program){const price=programPriceForType(program,row.passengerType);person.program={programId:program.program_id,name:program.program_name,qty:1,price,defaultPrice:price,priceReason:"ราคา Default ตามประเภทผู้โดยสาร"}}if(accommodation){person.accommodationId=accommodation.accommodation_id;person.accommodationName=accommodation.accommodation_name}person.accommodationBookedBy=String(row.accommodationBookedBy).includes("จองให้")?"company":"customer";delete person.programName;delete person.sourceRow;return person}
