function downloadPassengerCsvTemplate(){const header="คำนำหน้า,ชื่อ,นามสกุล,อายุ,เบอร์โทร,ประเภทผู้โดยสาร,สัญชาติ,โปรแกรม,จุดรับ,วิธีเดินทาง,ค่าเดินทาง,ที่พัก,ผู้จองที่พัก,เครดิตค่าเต็นท์,แพ้อาหาร,ข้อมูลสุขภาพ",sample="นาย,สมชาย,ใจดี,35,0812345678,ผู้ใหญ่,ไทย,ตั๋วเรือ,บขส.,รถตู้,400,,ลูกค้าจองเอง,0,,";const blob=new Blob(["\uFEFF"+header+"\r\n"+sample],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download="passenger-import-template.csv";link.click();URL.revokeObjectURL(url)}
const buildBookingWithoutTentRefund=buildBooking;buildBooking=function(){const booking=buildBookingWithoutTentRefund();booking.programRevenue=(booking.passengers||[]).reduce((sum,person)=>sum+Math.max(Number(person.program?.qty||1)*Number(person.program?.price||0),0),0);const remaining=Math.max(Number(booking.totalAmount||0)-Number(booking.depositAmount||0)-Number(booking.creditAmount||0),0);booking.paymentBreakdown={deposit:booking.depositPaymentMethod?{[booking.depositPaymentMethod]:Number(booking.depositAmount||0)}:{},credit:booking.creditPaymentMethod?{[booking.creditPaymentMethod]:Number(booking.creditAmount||0)}:{},remaining:booking.paymentMethod?{[booking.paymentMethod]:remaining}:{}};return booking};
const validateBookingBeforeBreakdown=validateBooking;validateBooking=function(booking){const base=validateBookingBeforeBreakdown(booking);if(base)return base;if((booking.passengers?.[0]?.islandAddOns||[]).some(item=>!String(item.name||"").trim()))return"กรุณากรอกชื่อรายการ Island Add-on ให้ครบ หรือลบแถวที่ไม่ใช้";for(const row of ["deposit","credit","remaining"]){const actual=paymentBreakdownSum(row),expected=paymentBreakdownExpected(row,Number(booking.totalAmount||0));if(actual&&Math.abs(actual-expected)>.009)return`ยอดแบ่งบัญชีแถว ${row} ต้องรวมเท่ากับ ${money(expected)} บาท`;}return""};
const documentGroupedItemsWithoutTentRefund=documentGroupedItems;documentGroupedItems=function(booking,profile){let rows=documentGroupedItemsWithoutTentRefund(booking,profile).filter(item=>!/เครดิต.*เต็นท์|คืนค่าเต็นท์/.test(item.name||"")),title=profile.title||"",islandNames=new Set((booking.passengers||[]).flatMap(person=>person.islandAddOns||[]).filter(item=>addonVisibleOnDocument(item,profile)).map(item=>item.name)),isIsland=item=>[...islandNames].some(name=>name&&(item.name||"").includes(name));if(title.includes("Register"))rows=rows.filter(item=>isIsland(item)||!/ค่าอุปกรณ์|ค่ารถตู้|ค่าเดินทาง/.test(item.name||""));else if(title==="ใบสำคัญรับเงิน")rows=rows.filter(item=>!/ค่ารถตู้|ค่าเดินทาง/.test(item.name||""));else if(title==="ใบอุปกรณ์")rows=rows.filter(item=>/ค่าอุปกรณ์/.test(item.name||""));else if(title==="ใบเสร็จรถตู้")rows=rows.filter(item=>isIsland(item)||/รถตู้|เดินทาง/.test(item.name||""));else if(title==="ตั๋วเรือ")rows=rows.filter(item=>isIsland(item)||!/ค่าอุปกรณ์|รถตู้|เดินทาง|ที่พัก/.test(item.name||""));return rows};
function paymentMethodMeta(name){return(master.paymentMethods||[]).find(method=>method.method_name===name)||{method_name:name||"ไม่ระบุ",payment_type:/สด/.test(name||"")?"cash":"transfer",show_on_money_receipt:true}}
function paymentTypeLabel(name){return paymentMethodMeta(name).payment_type==="cash"?"เงินสด":"โอนธนาคาร"}
function moneyReceiptAllocationTable(booking){const methods=(master.paymentMethods||[]).filter(method=>method.show_on_money_receipt!==false),deposit=Number(booking.depositAmount||0),credit=Number(booking.creditAmount||0),remaining=Math.max(Number(booking.totalAmount||0)-deposit-credit,0),breakdown=booking.paymentBreakdown||{},rows=[["มัดจำ","deposit",booking.depositPaymentMethod,deposit],["เชื่อ","credit",booking.creditPaymentMethod,credit],["ยอดที่เหลือ","remaining",booking.paymentMethod,remaining]];if(!methods.length)return"";return`<table class="document-table payment-allocation-table"><thead><tr><th>รายการ</th>${methods.map(method=>`<th>${escapeHtml(method.payment_type==="cash"?"เงินสด":`โอน ${method.method_name}`)}</th>`).join("")}</tr></thead><tbody>${rows.map(([label,key,selected,amount])=>{const hasSplit=Object.values(breakdown[key]||{}).some(Number);return`<tr><td>${label}</td>${methods.map(method=>{const value=Number(breakdown[key]?.[method.method_name]||0)||(hasSplit||selected!==method.method_name?0:amount);return`<td class="num">${value?money(value):""}</td>`}).join("")}</tr>`}).join("")}</tbody></table>`}
function documentFinancialSummary(booking,type){const total=Number(booking.totalAmount||0),deposit=Number(booking.depositAmount||0),credit=Number(booking.creditAmount||0),net=Math.max(total-deposit,0),depositName=type==="REGISTER"?paymentTypeLabel(booking.depositPaymentMethod):booking.depositPaymentMethod||"-";return`<div class="document-total document-financial-summary"><div class="document-total-row grand"><span>ยอดทั้งหมด</span><b>${money(total)} บาท</b></div><div class="document-total-row"><span>มัดจำ (${escapeHtml(depositName)})</span><b>${money(deposit)} บาท</b></div><div class="document-total-row grand"><span>ยอดสุทธิ</span><b>${money(net)} บาท</b></div>${type==="MONEY_RECEIPT"?`<div class="document-total-row"><span>ขายเชื่อ (${escapeHtml(booking.creditPaymentMethod||"-")})</span><b>${money(credit)} บาท</b></div>${moneyReceiptAllocationTable(booking)}`:""}</div>`}
const renderReceiptWithFinancialSummary=renderReceipt;renderReceipt=function(booking,type="MONEY_RECEIPT"){const html=renderReceiptWithFinancialSummary(booking,type);return["REGISTER","MONEY_RECEIPT"].includes(type)?html.replace('<div class="document-audit-line">',`${documentFinancialSummary(booking,type)}<div class="document-audit-line">`):html};
function renderIslandPurchaseOrder(booking){const company=getCompanySettings(),leader=[booking.leaderTitle,booking.leaderFirstName,booking.leaderLastName].filter(Boolean).join(" "),items=(booking.passengers||[]).flatMap(person=>person.islandAddOns||[]).filter(item=>addonVisibleOnDocument(item,documentProfiles.ISLAND_PURCHASE_ORDER)),total=items.reduce((sum,item)=>sum+Number(item.qty||1)*Number(item.price||0),0);return`<div class="document-actions"><button class="btn primary" onclick="window.print()">Print / Save PDF</button><button class="btn soft" onclick="window.close()">Close</button></div><div class="document-page document-island-purchase-order"><div class="document-header"><div class="document-company"><div><h2>${escapeHtml(company.company_name||"Sabina Tour Booking")}</h2><div>${escapeHtml(company.address||"")}</div><div>โทร ${escapeHtml(company.phone||"-")}</div></div></div><div class="document-title"><h1>ใบสั่งซื้อจากเกาะ</h1><div>Booking: ${escapeHtml(booking.bookingCode||"DRAFT")}</div><div>วันที่ออก: ${new Date().toLocaleDateString("th-TH")}</div></div></div><div class="document-meta"><div class="document-box"><strong>ผู้จอง</strong>${documentInfoLine("ชื่อหัวหน้าทริป",leader)}${documentInfoLine("Agent",booking.agentName)}</div><div class="document-box"><strong>กำหนดการ</strong>${documentInfoLine("วันไป",booking.travelDate)}${documentInfoLine("วันกลับ",booking.returnDate)}</div></div><h3>รายการ Island Add-on ที่สั่งซื้อ</h3><table class="document-table"><thead><tr><th>รายการ</th><th class="num">จำนวน</th><th class="num">ราคาต่อหน่วย</th><th>ช่องทางชำระเงิน</th><th class="num">รวม</th></tr></thead><tbody>${items.map(item=>`<tr><td>${escapeHtml(item.name||"อื่นๆ")}</td><td class="num">${Number(item.qty||1)}</td><td class="num">${money(item.price)}</td><td>${escapeHtml(item.paymentMethod||"ไม่ระบุ")}</td><td class="num">${money(Number(item.qty||1)*Number(item.price||0))}</td></tr>`).join("")||'<tr><td colspan="5">ไม่มี Island Add-on ที่เลือกสำหรับเอกสารนี้</td></tr>'}</tbody></table><div class="document-total"><div class="document-total-row grand"><span>รวมยอดสั่งซื้อ</span><b>${money(total)} บาท</b></div></div><div class="document-audit-line">จัดทำโดย ${escapeHtml(currentUser?.displayName||currentUser?.username||"ระบบ")} · พิมพ์ ${new Date().toLocaleString("th-TH")} · อ้างอิง ${escapeHtml(booking.bookingCode||"DRAFT")}</div><div class="document-footer"><div><div class="signature-line">ผู้สั่งซื้อ</div></div><div><div class="signature-line">ผู้รับคำสั่งซื้อ</div></div></div></div>`}
const renderReceiptBeforeIslandPurchaseOrder=renderReceipt;renderReceipt=function(booking,type="MONEY_RECEIPT"){return type==="ISLAND_PURCHASE_ORDER"?renderIslandPurchaseOrder(booking):renderReceiptBeforeIslandPurchaseOrder(booking,type)};
const refreshSummaryBeforeBulk=refreshSummary;refreshSummary=function(){refreshSummaryBeforeBulk();addLeaderApplyAllButton();renderPaymentBreakdownEditor();applyGroupBookingUi();applyGroupBookingUiV2()};
const startNewBookingBase=startNewBooking,loadBookingToFormBase=loadBookingToForm,bookingSearchTextBase=bookingSearchText,selectBookingBase=selectBooking;
startNewBooking=function(){paymentBreakdown={deposit:{},credit:{},remaining:{}};startNewBookingBase();for(const id of ["boatTicketBookNo","boatTicketNo"])document.getElementById(id).value="";renderPaymentBreakdownEditor();toggleEditBookingPrintActions(false)};
loadBookingToForm=function(booking){paymentBreakdown=structuredClone(booking.paymentBreakdown||{deposit:{},credit:{},remaining:{}});loadBookingToFormBase(booking);centralizeGroupPurchases();renderPassengers();refreshSummary();document.getElementById("boatTicketBookNo").value=booking.boatTicketBookNo||"";document.getElementById("boatTicketNo").value=booking.boatTicketNo||"";renderPaymentBreakdownEditor();toggleEditBookingPrintActions(true)};
bookingSearchText=function(booking){return `${bookingSearchTextBase(booking)} ${booking.boatTicketBookNo||""} ${booking.boatTicketNo||""}`.toLocaleLowerCase("th-TH")};
selectBooking=function(booking){selectBookingBase(booking);document.getElementById("bookingDetail").insertAdjacentHTML("beforeend",`<p>เล่มที่ (ตั๋วเรือ): ${escapeHtml(booking.boatTicketBookNo||"-")} | เลขที่ (ตั๋วเรือ): ${escapeHtml(booking.boatTicketNo||"-")}</p>`)};
(async()=>{startInactivityMonitor();applyAuth();if(currentUser){const last=Number(localStorage.getItem(ACTIVITY_KEY)||0);if(last&&Date.now()-last>=INACTIVITY_LIMIT_MS){logout("ออกจากระบบอัตโนมัติ เนื่องจากไม่มีการใช้งานเป็นเวลา 15 นาที");return}recordActivity()}if(currentUser?.mustChangePassword){showChangePassword(true);return}if(currentUser)await initData();})();
